module TopModule (
    input  clk,
    input  reset,
    input  in,
    output out
);

    // State encoding
    // 2'b00 -> State A
    // 2'b01 -> State B
    // 2'b10 -> State C
    // 2'b11 -> State D

    reg [1:0] state;
    reg [1:0] next_state;

    // Output logic (Moore machine): out is 1 only in state D
    assign out = (state == 2'b11) ? 1'b1 : 1'b0;

    // Next-state logic
    always @(*) begin
        case (state)
            2'b00: begin // State A
                if (in == 1'b0)
                    next_state = 2'b00; // A -> A
                else
                    next_state = 2'b01; // A -> B
            end
            2'b01: begin // State B
                if (in == 1'b0)
                    next_state = 2'b10; // B -> C
                else
                    next_state = 2'b01; // B -> B
            end
            2'b10: begin // State C
                if (in == 1'b0)
                    next_state = 2'b00; // C -> A
                else
                    next_state = 2'b11; // C -> D
            end
            2'b11: begin // State D
                if (in == 1'b0)
                    next_state = 2'b10; // D -> C
                else
                    next_state = 2'b01; // D -> B
            end
            default: next_state = 2'b00; // Fallback
        endcase
    end

    // State register with synchronous active-high reset
    always @(posedge clk) begin
        if (reset == 1'b1) begin
            state <= 2'b00; // Reset to State A
        end else begin
            state <= next_state;
        end
    end

endmodule

