module TopModule (
    input  clk,
    input  reset,
    input  data,
    output start_shifting
);

    // State encoding: 2 bits are sufficient for 4 states (S0-S3)
    // S0: 2'b00, S1: 2'b01, S2: 2'b10, S3: 2'b11
    reg [1:0] state;
    reg [1:0] next_state;

    // start_shifting output logic
    // It is set to 1 when transitioning from S3 to S1 (sequence 1101 found)
    // and held at 1 until reset.
    reg shifting_reg;
    assign start_shifting = shifting_reg;

    // State register (synchronous reset, positive edge triggered)
    always @(posedge clk) begin
        if (reset) begin
            state <= 2'b00;    // Reset to S0
            shifting_reg <= 1'b0;
        end else begin
            state <= next_state;
            // If we just entered S1 from S3 (i.e., found sequence 1101), set the flag
            // Note: We check if the next_state is S1 and the current state was S3.
            // Since we update state after computing next_state, we use a conditional here.
            // However, simpler approach: set the flag whenever next_state is S1 
            // AND the transition logic would have come from S3.
            // We can infer this by checking if data was 1 and state was S3.
            // Since 'state' here is the *old* state from the previous cycle perspective 
            // (or we can just check the condition that causes the transition).
            // Let's use the standard approach: output depends on current state and next state.
            // Actually, the spec says: "start_shifting is 1 only when the FSM transitions from state S3 to S1 upon receiving a data input of 1."
            // And "Once start_shifting is set to 1, it remains 1 indefinitely."
            // So we just need to detect the transition S3 -> S1 with data=1.

            // We can detect this by: (state == S3) && (data == 1) && (next_state == S1)
            if ((state == 2'b11) && (data == 1'b1) && (next_state == 2'b01)) begin
                shifting_reg <= 1'b1;
            end
            // Reset clears it, but we already handled reset above. 
            // If not resetting, and not the specific transition, it stays 1 (latched in shifting_reg).
        end
    end

    // Next state logic (combinational)
    always @(*) begin
        case (state)
            2'b00: // S0
                if (data == 1'b1)
                    next_state = 2'b01; // S1
                else
                    next_state = 2'b00; // S0

            2'b01: // S1
                if (data == 1'b0)
                    next_state = 2'b00; // S0
                else
                    next_state = 2'b10; // S2

            2'b10: // S2
                if (data == 1'b0)
                    next_state = 2'b11; // S3
                else
                    next_state = 2'b10; // S2 (stay on 111)

            2'b11: // S3
                if (data == 1'b1)
                    next_state = 2'b01; // S1 (and assert start_shifting)
                else
                    next_state = 2'b00; // S0

            default: next_state = 2'b00;
        endcase
    end

endmodule

