    reg [15:0] count_reg;

    // Combinational next-state logic
    always @(*) begin
        if (count_reg == 16'h9999) begin
            // Wrap around to 0 on next clock
            count_reg = 16'd0;
        end else begin
            // Increment BCD by 1
            count_reg = count_reg + 16'd1;
        end
    end

    // Synchronous active-high reset
