    assign q = count_reg;

    // Generate enable signals for ripple carry
    // ena[0] : ones digit always increments if not at 9
    // ena[1] : tens digit increments when ones digit == 9
    // ena[2] : hundreds digit increments when tens and ones digits == 9

    // Note: The ones digit increments on every clock (unless at 9 and wrapping),
    // but the enable signal indicates the condition for the next digit.
    assign ena[0] = 1'b1; // Always active high

    // Tens enable: high when ones digit (q[3:0]) is 9
    assign ena[1] = (count_reg[3:0] == 4'd9);

    // Hundreds enable: high when both ones and tens digits are 9
    // q[7:4] is the tens digit
    assign ena[2] = (count_reg[7:4] == 4'd9);

endmodule

