module TopModule (
    input  clk,
    input  resetn,
    input  x,
    input  y,
    output f,
    output g
);

    // State encoding
    typedef enum logic [2:0] {
        STATE_A   = 3'b000, // Initial/Reset state
        STATE_B   = 3'b001, // f-pulse state
        STATE_C   = 3'b010, // Monitor x for sequence 1,0,1
        STATE_D   = 3'b011, // Monitor y for timeout
        STATE_FAIL = 3'b100 // g=0 permanent failure state
    } state_t;

    // State register (synchronous, active-low reset)
    state_t state, next_state;

    // x-shift register to detect sequence 1, 0, 1
    // We use a 3-bit register where the MSB is the oldest and LSB is the newest
    logic [2:0] x_shift;

    // y-counter/Timer: 2-bit counter
    // Counts clock cycles with y=0. 
    // Value 2 (binary 10) means two cycles have passed with y=0.
    logic [1:0] y_counter;

    // Combinational assignments for outputs
    // f is 1 only in STATE_B
    assign f = (state == STATE_B) ? 1'b1 : 1'b0;

    // g is 1 in STATE_D, 0 elsewhere (including FAIL state)
    assign g = (state == STATE_D) ? 1'b1 : 1'b0;

    // ==========================================
    // 1. Next-State Logic (Combinational)
    // ==========================================

    always_comb begin
        // Default: stay in current state
        next_state = state;

        case (state)
            STATE_A: begin
                // When resetn is de-asserted (HIGH), transition to STATE_B after next clock edge.
                // Note: The state transition happens on the posedge clk.
                // Here we just set the next_state for the flip-flop update.
                if (~resetn)
                    next_state = STATE_A;
                else
                    next_state = STATE_B;
            end

            STATE_B: begin
                // Output f=1 for this cycle, then move to STATE_C
                next_state = STATE_C;
            end

            STATE_C: begin
                // Check if x-shift register contains 101
                if (x_shift == 3'b101)
                    next_state = STATE_D; // Sequence detected
                else
                    next_state = STATE_C; // Stay in C
            end

            STATE_D: begin
                // Check y-counter and y input
                // If y == 1, reset counter and stay in D
                // If y == 0, increment counter
                // If counter reaches 2 (two cycles of y=0), go to FAIL
                if (y == 1'b1) begin
                    // y became 1 within the allowed time
                    next_state = STATE_D; // Maintain g=1
                end else begin
                    // y is 0
                    if (y_counter == 2'b10) begin
                        // Two cycles of y=0 passed -> Failure
                        next_state = STATE_FAIL;
                    end else begin
                        // Continue monitoring
                        next_state = STATE_D;
                    end
                end
            end

            STATE_FAIL: begin
                // Absorbing state: stay forever until reset
                if (~resetn)
                    next_state = STATE_A;
                else
                    next_state = STATE_FAIL;
            end

            default: next_state = STATE_A;
        endcase
    end

    // ==========================================
    // 2. State Register Update (Sequential)
    // ==========================================

    always_ff @(posedge clk or negedge resetn) begin
        if (~resetn) begin
            // Synchronous reset: go to STATE_A and reset all internal registers
            state       <= STATE_A;
            x_shift     <= 3'b000;
            y_counter   <= 2'b00;
        end else begin
            state       <= next_state;

            // Update x-shift register on every clock cycle (when not in reset)
            // Shift logic: new x goes to LSB, old bits shift left
            // New sequence: x, old_x_shift[2:1]
            x_shift     <= {x_shift[2:1], x};

            // Update y-counter
            // Logic: 
            // If y == 1: counter resets to 0
            // If y == 0: counter increments, but max value is 2 (binary 10)
            // We implement a simple increment with limit check.
            if (y == 1'b1) begin
                y_counter <= 2'b00;
            end else begin
                // Increment if not already at limit (2)
                // y_counter + 1, but if y_counter == 2, stay at 2
                if (y_counter == 2'b10)
                    y_counter <= 2'b10; // Stay at limit
                else
                    y_counter <= y_counter + 1'b1;
            end
        end
    end

endmodule

