    output fr1,
    output fr0,
    output dfr
);

    // State register: 2 bits encoding the previous sensor configuration
    // 00: Below s[0] (no sensors)
    // 01: Between s[1] and s[0] (s[0] asserted)
    // 10: Between s[2] and s[1] (s[1] asserted)
    // 11: Above s[2] (s[2] asserted)
    reg [1:0] PS, NS;

    // Combinational signals for current level decoding
    wire above_s2   = s[2];
    wire between_s2_s1 = s[1] & ~s[2];
    wire between_s1_s0 = s[0] & ~s[1] & ~s[2];
    wire below_s0   = ~s[0] & ~s[1] & ~s[2];

    // Current level as 2-bit code (same encoding as PS)
    // 00: below_s0, 01: between_s1_s0, 10: between_s2_s1, 11: above_s2
    wire [1:0] current_level;
    assign current_level = (above_s2)    ? 2'b11 :
                           (between_s2_s1)? 2'b10 :
                           (between_s1_s0)? 2'b01 :
                                          2'b00;

    // ==================================================
    // State Register (Flip-flops)
    // ==================================================
    always @(posedge clk or posedge reset) begin
        if (reset)
            PS <= 2'b00;  // Reset: "low water level for a long time"
        else
            PS <= NS;
    end

    // ==================================================
    // Next State Logic
    // ==================================================
    always @(*) begin
        // Default: keep current state if no change detected
        NS = PS;

        // Rising edge detection: current level is "higher" than previous state
        // We define "higher" as current_level having a greater binary value than PS.
        // This naturally handles transitions like 00->01, 00->10, 00->11, 01->10, 01->11, 10->11.
        if (current_level > PS) begin
            NS = current_level;
        end
        // Falling edge: current level is lower. We still update NS to current_level
        // so the state tracks the drop, but dfr will be 0 (since PS_prev was higher).
        // The specification says: "If the current level is lower than the previous level,
        // the state NS is updated to reflect the current level (to track the drop for future comparisons)."
        else if (current_level < PS) begin
            NS = current_level;
        end
        // No change: current_level == PS -> NS retains PS (already default)
    end

    // ==================================================
    // Output Logic (Combinational)
    // ==================================================

    // dfr: Supplemental flow valve
    // Asserted if previous level was lower than current level.
    // Since NS is updated on the clock edge, we must compare the *previous* PS
    // (the value stored in the register before the current update) with current_level.
    // However, in a pure combinational output block, PS holds the value from the
    // previous clock cycle. We XOR to check for a rise.
    // dfr = 1 if current_level > PS (previous state)
    assign dfr = (current_level > PS) ? 1'b1 : 1'b0;

    // Nominal flow outputs based on current level
    // Above s[2] (11): All 0
    // Between s[2] and s[1] (10): fr0=1
    // Between s[1] and s[0] (01): fr0=1, fr1=1
    // Below s[0]  (00): All 1

    assign fr0 = (current_level == 2'b01) || (current_level == 2'b00) ? 1'b1 : 1'b0;
    // Simplified: fr0 is 1 for levels 01 and 00 (Between s1-s0 and Below s0)
    // But table says: Below s0 -> all 1. Between s1-s0 -> fr0, fr1.
    // Above s2 and Between s2-s1 -> fr0 only (or none for above s2).
    // Let's re-verify table:
    // Above s2: None -> fr0=0, fr1=0, fr2=0
    // Between s2-s1: fr0
    // Between s1-s0: fr0, fr1
    // Below s0: fr0, fr1, fr2

    // Correct assignment based strictly on table:
    // fr0 is asserted in: Between s2-s1, Between s1-s0, Below s0.
    // fr1 is asserted in: Between s1-s0, Below s0.
    // fr2 is asserted in: Below s0 only.

    // Using current_level codes:
    // 11 (Above s2): fr0=0, fr1=0, fr2=0
    // 10 (Between s2-s1): fr0=1, fr1=0, fr2=0
    // 01 (Between s1-s0): fr0=1, fr1=1, fr2=0
    // 00 (Below s0):   fr0=1, fr1=1, fr2=1

    assign fr0 = (current_level != 2'b11) ? 1'b1 : 1'b0;
    assign fr1 = (current_level == 2'b01) || (current_level == 2'b00) ? 1'b1 : 1'b0;
    assign fr2 = (current_level == 2'b00) ? 1'b1 : 1'b0;

endmodule

