module TopModule(
    input wire d,
    input wire done_counting,
    input wire ack,
    input wire [9:0] state, // One-hot encoded: S(0), S1(1), S11(2), S110(3), B0(4), B1(5), B2(6), B3(7), Count(8), Wait(9)

    output reg B3_next,
    output reg S_next,
    output reg S1_next,
    output reg Count_next,
    output reg Wait_next,
    output reg done,
    output reg counting,
    output reg shift_ena
);

    // --- Next-State Logic (Combinational) ---

    // S_next: Transitions to S from S (/d), S1 (/d), S110 (/d)
    assign S_next = (~d & state[0]) | (~d & state[1]) | (~d & state[3]);

    // S1_next: Transitions to S1 from S (d)
    assign S1_next = (d & state[0]);

    // S11_next: Transitions to S11 from S1 (d) or S11 (d)
    assign S11_next = (d & state[1]) | (d & state[2]);

    // S110_next: Transitions to S110 from S11 (/d)
    assign S110_next = (~d & state[2]);

    // B0_next: Transitions to B0 from S11 (d)
    assign B0_next = (d & state[2]);

    // B1_next: Always from B0
    assign B1_next = state[4];

    // B2_next: Always from B1
    assign B2_next = state[5];

    // B3_next: Always from B2
    assign B3_next = state[6];

    // Count_next: From B3 (always), from Count (/done_counting), from Wait (/ack)
    assign Count_next = state[7] | (~done_counting & state[8]) | (~ack & state[9]);

    // Wait_next: From Count (done_counting)
    assign Wait_next = (done_counting & state[8]);

    // --- Output Logic (Moore Machine) ---

    // shift_ena: Asserted for B0, B1, B2, B3
    assign shift_ena = state[4] | state[5] | state[6] | state[7];

    // counting: Asserted for Count
    assign counting = state[8];

    // done: Asserted for Wait
    assign done = state[9];

endmodule

