module TopModule (
    input  clk,
    input  reset,
    input  [7:0] in,
    output reg [23:0] out_bytes,
    output reg done
);

    // State encoding
    parameter IDLE   = 2'b00;
    parameter BYTE1  = 2'b01;
    parameter BYTE2  = 2'b10;
    parameter BYTE3  = 2'b11;

    // State register
    reg [1:0] state;
    reg [7:0] byte1_reg, byte2_reg, byte3_reg;

    // ==================================================
    // 1. Sequential Logic (Positive Edge-Triggered)
    // ==================================================
    always @(posedge clk) begin
        if (reset) begin
            // Synchronous reset: go to IDLE, clear outputs
            state       <= IDLE;
            out_bytes   <= 24'h0;
            done        <= 1'b0;
            byte1_reg   <= 8'h0;
            byte2_reg   <= 8'h0;
            byte3_reg   <= 8'h0;
        end else begin
            case (state)
                IDLE: begin
                    // Wait until in[3] is high to start a message
                    if (in[3]) begin
                        state       <= BYTE1;
                        byte1_reg   <= in;
                        done        <= 1'b0;
                    end else begin
                        // Stay in IDLE, outputs unchanged
                        state       <= IDLE;
                        done        <= 1'b0;
                    end
                end

                BYTE1: begin
                    // Move to BYTE2, store current in as second byte
                    state       <= BYTE2;
                    byte2_reg   <= in;
                end

                BYTE2: begin
                    // Move to BYTE3, store current in as third byte
                    state       <= BYTE3;
                    byte3_reg   <= in;
                end

                BYTE3: begin
                    // Assert done high for one cycle
                    done        <= 1'b1;
                    // Assemble the 24-bit message
                    out_bytes   <= {byte1_reg, byte2_reg, byte3_reg};
                    // Transition back to IDLE
                    state       <= IDLE;
                end
            endcase
        end
    end

endmodule

