module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    // State encoding
    // 2'b00: WALKING
    // 2'b01: FALLING
    // 2'b10: DIGGING
    // 2'b11: SPLATTERED
    reg [1:0] state, next_state;

    // Walking direction register (preserved during fall/dig)
    // 1'b0 = left, 1'b1 = right
    reg walk_dir, next_walk_dir;

    // Fall counter (5 bits: counts 0 to 21+)
    reg [4:0] fall_counter, next_fall_counter;

    // Assign outputs based on current state (Moore machine)
    assign walk_left = (state == 2'b00) && (walk_dir == 1'b0);
    assign walk_right = (state == 2'b00) && (walk_dir == 1'b1);
    assign aaah = (state == 2'b01);
    assign digging = (state == 2'b10);

    // State transition logic (sequential always block)
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= 2'b00;       // WALKING
            walk_dir <= 1'b0;     // Default direction: Left
            fall_counter <= 5'd0;
        end else begin
            state <= next_state;
            walk_dir <= next_walk_dir;
            fall_counter <= next_fall_counter;
        end
    end

    // Next-state and output logic (combinational always block)
    always @(*) begin
        // Default assignments for next state and registers
        next_state = state;
        next_walk_dir = walk_dir;
        next_fall_counter = fall_counter;

        case (state)
            2'b00: begin // WALKING on ground
                // Priority: Fall > Dig > Direction Change
                if (ground == 1'b0) begin
                    // Fall takes precedence
                    next_state = 2'b01; // FALLING
                    next_fall_counter = 5'd1;
                end else if (dig == 1'b1) begin
                    // Dig while on ground
                    next_state = 2'b10; // DIGGING
                end else begin
                    // Check bumpers for direction change
                    if (bump_left == 1'b1 && bump_right == 1'b1) begin
                        // Bumped on both sides: switch direction
                        next_walk_dir = ~walk_dir;
                    end else if (bump_left == 1'b1) begin
                        // Bumped on left: walk right
                        next_walk_dir = 1'b1;
                    end else if (bump_right == 1'b1) begin
                        // Bumped on right: walk left
                        next_walk_dir = 1'b0;
                    end
                    // else: maintain current direction
                end
            end

            2'b01: begin // FALLING
                // Logic handles transition out of falling state
                if (ground == 1'b0) begin
                    // Still in the air, increment counter
                    next_fall_counter = fall_counter + 1'b1;
                end else begin
                    // ground == 1: The Lemming hit the ground.
                    // Check splatter condition.
                    // "if a Lemming falls for more than 20 clock cycles then hits the ground"
                    // If fall_counter > 20, splatter.
                    if (fall_counter > 5'd20) begin
                        // Splatters
                        next_state = 2'b11; // SPLATTERED
                    end else begin
                        // Resume walking in original direction
                        next_state = 2'b00; // WALKING
                        // walk_dir is preserved (next_walk_dir default is walk_dir)
                    end
                end
            end

            2'b10: begin // DIGGING
                // Priority: Fall > Dig > Direction Change
                // We are already in Dig state.
                // Transitions:
                // 1. Fall: if ground == 0
                // 2. Stay digging if ground == 1

                if (ground == 1'b0) begin
                    // Fall into hole
                    next_state = 2'b01; // FALLING
                    next_fall_counter = 5'd1;
                end else begin
                    // Still on ground. Continue digging.
                    // Spec: "will continue digging until it reaches the other side (ground=0)".
                    // The dig input starts it, but once in state, it continues as long as ground=1.
                    // We do not change state, so we stay in DIGGING.
                end
            end

            2'b11: begin // SPLATTERED
                // Remain in this state indefinitely
                // Only exit on areset (handled in sequential block)
                // Outputs are already 0 by assignment.
            end
        endcase
    end

endmodule
